//go:build ppc64le

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 VSX kernels (binop32.go), generated by
// go-asmgen (binop32_ppc64le_gen.go) into binop32_ppc64le.s, gated on hasVSX
// (kernels_ppc64le.go; ISA-2.06 operations only, the POWER8 baseline). One IEEE
// binary32 operation per element, no fused instruction: bit-identical to the
// portable loops. The callers pass every slice already sliced to the common
// length; an empty one never reaches a kernel.
//
//go:noescape
func add32VSX(dst, a, b *float32, n int)

//go:noescape
func sub32VSX(dst, a, b *float32, n int)

//go:noescape
func mul32VSX(dst, a, b *float32, n int)

//go:noescape
func div32VSX(dst, a, b *float32, n int)

//go:noescape
func sqrt32VSX(dst, src *float32, n int)

func add32(dst, a, b []float32) {
	if len(a) == 0 || !hasVSX {
		add32Ref(dst, a, b)
		return
	}
	add32VSX(&dst[0], &a[0], &b[0], len(a))
}

func sub32(dst, a, b []float32) {
	if len(a) == 0 || !hasVSX {
		sub32Ref(dst, a, b)
		return
	}
	sub32VSX(&dst[0], &a[0], &b[0], len(a))
}

func mul32(dst, a, b []float32) {
	if len(a) == 0 || !hasVSX {
		mul32Ref(dst, a, b)
		return
	}
	mul32VSX(&dst[0], &a[0], &b[0], len(a))
}

func div32(dst, a, b []float32) {
	if len(a) == 0 || !hasVSX {
		div32Ref(dst, a, b)
		return
	}
	div32VSX(&dst[0], &a[0], &b[0], len(a))
}

func sqrt32(dst, src []float32) {
	if len(src) == 0 || !hasVSX {
		sqrt32Ref(dst, src)
		return
	}
	sqrt32VSX(&dst[0], &src[0], len(src))
}
